function leerFormulario(form) {
  const datos = Object.fromEntries(new FormData(form));
  datos.cant = Number(datos.cant) || 1;
  datos.activo = form.elements.activo?.checked ?? false;
  datos.cliente = (datos.cliente || '').trim();
  return datos;
}

function validarActividad(d, existentes) {
  const errores = [];
  if (!d.cliente) errores.push({ campo: 'cliente', msg: 'Escribe el cliente.' });
  if (!d.fecha) errores.push({ campo: 'fecha', msg: 'Elige la fecha.' });
  if (existentes.some(a => a.chasis === d.chasis && a.id !== d.id))
    errores.push({ campo: 'chasis', msg: 'Ese chasis ya tiene una actividad.' });
  return errores;
}

function abrirFormulario(act = {}) {
  const f = $('form-actividad');
  f.reset();
  for (const [k, v] of Object.entries(act)) if (f.elements[k]) f.elements[k].value = v;
  $('dlg-actividad').showModal();
}
$('form-actividad').addEventListener('submit', e => {
  e.preventDefault();
  const d = leerFormulario(e.target);
  const errores = validarActividad(d, S.acts);
  if (errores.length) return mostrarErrores(e.target, errores);
  if (d.id) Object.assign(S.acts.find(a => a.id === d.id), d);
  else S.acts.push({ ...d, id: crypto.randomUUID(), estado: 'Pendiente' });
  $('dlg-actividad').close();
  guardarYRedibujar();
});

