function abrirBD() {
  return new Promise((ok, mal) => {
    const pet = indexedDB.open('planificador', 1);
    pet.onupgradeneeded = () => {            // solo al crear o subir la versión
      const bd = pet.result;
      if (!bd.objectStoreNames.contains('fotos')) bd.createObjectStore('fotos', { keyPath: 'id' });
    };
    pet.onsuccess = () => ok(pet.result);
    pet.onerror = () => mal(pet.error);
  });
}

async function operar(almacen, modo, fn) {
  const bd = await abrirBD();
  return new Promise((ok, mal) => {
    const tx = bd.transaction(almacen, modo);
    const pet = fn(tx.objectStore(almacen));
    tx.oncomplete = () => ok(pet?.result);
    tx.onerror = () => mal(tx.error);
  });
}

const guardar = (almacen, obj) => operar(almacen, 'readwrite', s => s.put(obj));
const leer    = (almacen, id)  => operar(almacen, 'readonly',  s => s.get(id));
const todos   = almacen        => operar(almacen, 'readonly',  s => s.getAll());
const borrar  = (almacen, id)  => operar(almacen, 'readwrite', s => s.delete(id));

